// Static site data generated by scraper/5-build-data.js
import products from '../data/products.json'
import articles from '../data/articles.json'
import site from '../data/site.json'
import showrooms from '../data/showrooms.json'

export { products, articles, site, showrooms }

export const productBySlug = (slug) => products.find((p) => p.slug === slug)
export const articleBySlug = (slug) => articles.find((a) => a.slug === slug)

export const brands = site.brands

const priced = products.filter((p) => p.price)
export const minPrice = Math.min(...priced.map((p) => p.price))

// One standout model per brand for the hero and home picks:
// priced, full specs, transparent photo, newest first
export const featured = brands
  .map(({ name }) =>
    products
      .filter((p) => p.brand === name && p.price && p.transparent && Object.keys(p.specs).length)
      .sort((a, b) => b.id - a.id)[0],
  )
  .filter(Boolean)

export const SPEC_KEYS = ['Jarak Tempuh', 'Kecepatan Max', 'Kapasitas Baterai', 'Beban Max', 'Durasi Charger']
